"""Numerical fixtures generated by the authors' pinned public implementations."""
import json
import tempfile
import unittest
from collections import OrderedDict
from pathlib import Path
from types import SimpleNamespace

import torch
from dominant_layer_zo.config import load_config, validate
from dominant_layer_zo.methods.agzo import AGZOStep
from dominant_layer_zo.methods.seeds import sample_seed
from dominant_layer_zo.sparse import SparseMeZOStep
from test_sparse import config, trainer, FAMILIES
from test_core import tiny
from test_resume import InterruptAfterSave


class ReferenceTests(unittest.TestCase):
    def test_shipped_configs_load_and_baselines_are_full(self):
        root = Path(__file__).resolve().parents[1]
        configs = {p.relative_to(root).as_posix(): load_config(p)
                   for p in (root / 'configs').rglob('*.yaml')}
        for family in FAMILIES:
            for method in ('agzo', 'sparse_mezo'):
                c = configs[f'configs/{family}/{method}_full.yaml']
                self.assertEqual(c['training']['scope'], 'full')
                self.assertIsNone(c['training']['layer'])
                self.assertTrue(c['model']['fp32_attention_scores'])
                self.assertFalse((root / f'configs/{family}/{method}_layer.yaml').exists())
                c['training'].update(scope='layer', layer=1)
                with self.assertRaisesRegex(ValueError, 'full-model baselines'):
                    validate(c)

    def test_public_code_fp32_algorithm_parity(self):
        data = json.loads((Path(__file__).parent / 'fixtures/reference_steps.json').read_text())
        for fixture in data['fixtures']:
            with self.subTest(method=fixture['method'], scope=fixture['scope'],
                              ratio=fixture.get('selected_ratio')):
                model = torch.nn.Sequential(OrderedDict([
                    ('first', torch.nn.Linear(5, 4)), ('activation', torch.nn.Tanh()),
                    ('second', torch.nn.Linear(4, 3)), ('norm', torch.nn.LayerNorm(3))]))
                with torch.no_grad():
                    for name, p in model.named_parameters():
                        p.copy_(torch.tensor(fixture['initial'][name]))
                        p.requires_grad_(fixture['scope'] == 'full' or name.startswith('second.'))
                x = torch.tensor(fixture['input'])
                target = torch.tensor(fixture['target'])
                torch.manual_seed(data['torch_seed'])
                state = SimpleNamespace(seed=data['perturbation_seed'])
                if fixture['method'] == 'agzo':
                    stepper = AGZOStep(model, [(n, p) for n, p in model.named_parameters() if p.requires_grad],
                        rank=fixture['rank'], power_iterations=fixture['power_iterations'])
                else:
                    stepper = SparseMeZOStep(model.named_parameters(), fixture['selected_ratio'])
                for expected in fixture['steps']:
                    loss, _ = stepper.step(lambda: (model(x) - target).square().mean(),
                        seed=sample_seed(state), epsilon=data['epsilon'], lr=data['lr'])
                    self.assertAlmostEqual(loss.item(), expected['loss'], delta=2e-5)
                    for name, p in model.named_parameters():
                        torch.testing.assert_close(p, torch.tensor(expected['parameters'][name]),
                                                   rtol=2e-5, atol=2e-6, msg=name)

    def test_sparse_scopes_precisions_and_resume(self):
        for family in FAMILIES:
            for scope in ('full',):
                for dtype in ('float32', 'float16'):
                    with self.subTest(family=family, scope=scope, dtype=dtype), tempfile.TemporaryDirectory() as td:
                        c = config(family, Path(td)/'expected', scope)
                        c['training']['noise'] = 'gaussian'
                        c['training']['seed'] = 123
                        c['data']['seed'] = 17
                        c['model']['dtype'] = dtype
                        validate(c)
                        def make():
                            model = tiny(family).to(getattr(torch, dtype))
                            if family == 'llama2':
                                model.config.fp32_attention_scores = True
                            return trainer(c, model)
                        expected = make()
                        before = {n: p.detach().clone() for n, p in expected.model.named_parameters()}
                        expected.train()
                        eligible = {g.name for g in expected.sparse_param_groups}
                        self.assertTrue(all('norm' not in n for n in eligible))
                        self.assertTrue(any(not torch.equal(p, before[n]) for n, p in expected.model.named_parameters()))
                        for n, p in expected.model.named_parameters():
                            self.assertTrue(torch.isfinite(p).all(), n)
                            if n not in eligible:
                                torch.testing.assert_close(p, before[n], rtol=0, atol=0, msg=n)
                        for group in expected.sparse_param_groups:
                            outside = before[group.name].abs() >= group.threshold
                            torch.testing.assert_close(group.param[outside], before[group.name][outside],
                                                       rtol=0, atol=0, msg=group.name)
                        c['output_dir'] = str(Path(td)/'interrupted')
                        c['checkpoint'].update(strategy='steps', save_steps=1)
                        first = make()
                        first.add_callback(InterruptAfterSave())
                        with self.assertRaisesRegex(RuntimeError, 'simulated interruption'):
                            first.train()
                        resumed = make()
                        resumed.train(resume_from_checkpoint=str(Path(c['output_dir'])/'checkpoint-1'))
                        for (n, p), (_, q) in zip(expected.model.named_parameters(), resumed.model.named_parameters()):
                            torch.testing.assert_close(p, q, rtol=0, atol=0, msg=n)
                        self.assertEqual(sample_seed(expected), sample_seed(resumed))
                        for a, b in zip(expected.sparse_param_groups, resumed.sparse_param_groups):
                            torch.testing.assert_close(a.threshold, b.threshold, rtol=0, atol=0)

    def test_config_guards(self):
        for section, key, value in [('training', 'noise', 'rademacher'),
                                   ('training', 'directions', 2), ('training', 'max_zo_coeff', 1.),
                                   ('training', 'seed', 2**32), ('sparse', 'exclude_keywords', [])]:
            c = config('llama2', 'unused')
            c['training']['noise'] = 'gaussian'
            c[section][key] = value
            with self.subTest(section=section, key=key), self.assertRaises(ValueError):
                validate(c)


if __name__ == '__main__':
    unittest.main()
